{
  "name": "SinapsisBot - 3D Printing Assistant",
  "description": "An intelligent assistant for Sinapsis 3D in Bariloche, helping Maru manage stock, calculate budgets, and organize the production queue with an Argentinian personality.",
  "requestFramePermissions": ["microphone"]
}

export enum OrderStatus {
  PENDIENTE = 'Pendiente',
  EN_DISENO = 'En Diseño',
  IMPRIMIENDO = 'Imprimiendo',
  LISTO = 'Listo para entregar',
  ENTREGADO = 'Entregado'
}

export enum FilamentType {
  PLA = 'PLA',
  PETG = 'PET-G'
}

export interface StockItem {
  id: string;
  color: string;
  type: FilamentType;
  quantity: number; // In grams
  status: 'Ok' | 'Bajo' | 'Crítico';
}

export interface Order {
  id: string;
  customer: string;
  details: string;
  status: OrderStatus;
  priority: 'Alta' | 'Media' | 'Baja';
  createdAt: string;
}

export interface PriceSettings {
  filamentPricePerKilo: number;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
}

import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const getStockDeclaration: FunctionDeclaration = {
  name: 'get_stock',
  description: 'Obtiene la lista actual de stock de filamentos (colores y tipos).',
  parameters: { type: Type.OBJECT, properties: {} }
};

const updateStockDeclaration: FunctionDeclaration = {
  name: 'update_stock',
  description: 'Actualiza el stock de un filamento específico.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      color: { type: Type.STRING },
      type: { type: Type.STRING, enum: ['PLA', 'PET-G'] },
      grams: { type: Type.NUMBER, description: 'Cantidad en gramos a establecer' }
    },
    required: ['color', 'type', 'grams']
  }
};

const getOrdersDeclaration: FunctionDeclaration = {
  name: 'get_orders',
  description: 'Obtiene la lista de pedidos en la cola de producción.',
  parameters: { type: Type.OBJECT, properties: {} }
};

const addOrderDeclaration: FunctionDeclaration = {
  name: 'add_order',
  description: 'Registra un nuevo pedido en la cola.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      customer: { type: Type.STRING },
      details: { type: Type.STRING },
      priority: { type: Type.STRING, enum: ['Alta', 'Media', 'Baja'] }
    },
    required: ['customer', 'details']
  }
};

export class SinapsisBotService {
  private chat;

  constructor(
    private stock: any[], 
    private orders: any[], 
    private onStateChange: (newState: { stock?: any[], orders?: any[] }) => void
  ) {
    this.chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{
          functionDeclarations: [
            getStockDeclaration,
            updateStockDeclaration,
            getOrdersDeclaration,
            addOrderDeclaration
          ]
        }]
      }
    });
  }

  async sendMessage(message: string) {
    const result = await this.chat.sendMessage({ message });

    if (result.functionCalls) {
      const toolResponses: any[] = [];

      for (const call of result.functionCalls) {
        let response;
        if (call.name === 'get_stock') {
          response = { result: this.stock };
        } else if (call.name === 'update_stock') {
          const { color, type, grams } = call.args as any;
          const updatedStock = this.stock.map(s => 
            (s.color.toLowerCase() === color.toLowerCase() && s.type === type) 
              ? { ...s, quantity: grams, status: grams < 200 ? 'Crítico' : (grams < 500 ? 'Bajo' : 'Ok') } 
              : s
          );
          this.onStateChange({ stock: updatedStock });
          response = { result: "Stock actualizado correctamente ✅" };
        } else if (call.name === 'get_orders') {
          response = { result: this.orders };
        } else if (call.name === 'add_order') {
          const { customer, details, priority = 'Media' } = call.args as any;
          const newOrder = {
            id: 'o' + Math.random().toString(36).substr(2, 4),
            customer,
            details,
            status: 'Pendiente',
            priority,
            createdAt: new Date().toISOString().split('T')[0]
          };
          const updatedOrders = [newOrder, ...this.orders];
          this.onStateChange({ orders: updatedOrders });
          response = { result: "Pedido anotado che! Lo puse como pendiente 🖨️" };
        }

        toolResponses.push({
          id: call.id,
          name: call.name,
          response
        });
      }

      const finalResult = await this.chat.sendMessage({
        // We need to send the tool responses back to continue the flow
        message: "Procesado." 
      });

      // Note: In a real implementation we should handle subsequent function calls if any
      // but for this scope we'll assume one turn of tool usage is enough.
      return finalResult.text;
    }

    return result.text;
  }
}

