interface StockBoardProps {
  stock: StockItem[];
  onUpdateStock?: (id: string, updates: Partial<StockItem>) => void;
}

const StockBoard: React.FC<StockBoardProps> = ({ stock, onUpdateStock }) => {
  const [activeType, setActiveType] = useState<FilamentType>(FilamentType.PLA);

  const filteredStock = stock.filter(item => item.type === activeType);

  const updateCount = (id: string, field: 'closedCount' | 'openCount', delta: number) => {
    const item = stock.find(s => s.id === id);
    if (!item || !onUpdateStock) return;
    const newVal = Math.max(0, item[field] + delta);
    onUpdateStock(id, { [field]: newVal });
  };

  const updateStatus = (id: string, status: SpoolStatus) => {
    if (onUpdateStock) onUpdateStock(id, { openStatus: status });
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Inventario de Filamentos</h2>
          <p className="text-slate-500 text-sm">Control de rollos abiertos y cerrados</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-2xl w-fit">
          <button 
            onClick={() => setActiveType(FilamentType.PLA)}
            className={`px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeType === FilamentType.PLA ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            PLA
          </button>
          <button 
            onClick={() => setActiveType(FilamentType.PETG)}
            className={`px-6 py-2 rounded-xl text-sm font-bold transition-all ${activeType === FilamentType.PETG ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            PET-G
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredStock.map((item) => (
          <div key={item.id} className="bg-white p-5 rounded-3xl shadow-sm border border-slate-200 flex flex-col gap-4">
            <div className="flex items-center gap-3">
              <div 
                className="w-10 h-10 rounded-2xl shadow-inner flex items-center justify-center"
                style={{ backgroundColor: getHexColor(item.color) }}
              >
                <Droplet size={18} className={isDark(item.color) ? 'text-white/40' : 'text-black/20'} />
              </div>
              <h3 className="font-bold text-slate-800 leading-tight">{item.color}</h3>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Cerrados</p>
                <div className="flex items-center justify-between">
                  <button onClick={() => updateCount(item.id, 'closedCount', -1)} className="p-1 hover:bg-slate-200 rounded-lg text-slate-400"><Minus size={14} /></button>
                  <span className="font-black text-slate-700">{item.closedCount}</span>
                  <button onClick={() => updateCount(item.id, 'closedCount', 1)} className="p-1 hover:bg-slate-200 rounded-lg text-indigo-600"><Plus size={14} /></button>
                </div>
              </div>
              <div className="bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">Abiertos</p>
                <div className="flex items-center justify-between">
                  <button onClick={() => updateCount(item.id, 'openCount', -1)} className="p-1 hover:bg-slate-200 rounded-lg text-slate-400"><Minus size={14} /></button>
                  <span className="font-black text-slate-700">{item.openCount}</span>
                  <button onClick={() => updateCount(item.id, 'openCount', 1)} className="p-1 hover:bg-slate-200 rounded-lg text-indigo-600"><Plus size={14} /></button>
                </div>
              </div>
            </div>

            {item.openCount > 0 && (
              <div className="space-y-2">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Estado del abierto</p>
                <div className="flex flex-wrap gap-1">
                  {(['Casi completo', 'A la mitad', 'Casi vacío'] as SpoolStatus[]).map((status) => (
                    <button
                      key={status}
                      onClick={() => updateStatus(item.id, status)}
                      className={`text-[10px] px-2 py-1.5 rounded-lg font-bold border transition-all flex-1 ${item.openStatus === status ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-500 border-slate-100 hover:border-slate-200'}`}
                    >
                      {status}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {item.closedCount === 0 && item.openStatus === 'Casi vacío' && (
              <div className="flex items-center gap-2 text-red-500 bg-red-50 p-2 rounded-xl border border-red-100">
                <Info size={12} />
                <span className="text-[10px] font-bold uppercase">¡Reponer urgente!</span>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

// Helper simple para colores
function getHexColor(color: string) {
  const map: any = {
    "Negro": "#1a1a1a", "Blanco": "#ffffff", "Gris": "#94a3b8", "Gris claro": "#cbd5e1",
    "Gris Plata": "#e2e8f0", "Azul": "#2563eb", "Celeste": "#60a5fa", "Aqua": "#2dd4bf",
    "Rojo": "#dc2626", "Dorado": "#fbbf24", "Amarillo": "#fde047", "Naranja": "#f97316",
    "Piel": "#ffedd5", "Verde claro": "#4ade80", "Verde Oscuro": "#166534", "Rosa": "#f472b6",
    "Violeta": "#8b5cf6", "Lila": "#ddd6fe", "Fucsia": "#db2777", "Marron": "#78350f",
    "Marron chocolate": "#451a03", "Celeste claro (pastel)": "#bfdbfe"
  };
  return map[color] || "#ccc";
}

function isDark(color: string) {
  const darks = ["Negro", "Azul", "Rojo", "Verde Oscuro", "Marron", "Marron chocolate", "Violeta", "Fucsia"];
  return darks.includes(color);
}

