                    <button onClick={() => updateCount(item.id, 'openCount', -1)} className="p-1 hover:bg-slate-100 rounded-lg text-slate-400"><Minus size={14} /></button>
                    <span className="font-black text-slate-700">{item.openCount}</span>
                    <button onClick={() => updateCount(item.id, 'openCount', 1)} className="p-1 hover:bg-slate-100 rounded-lg text-indigo-600"><Plus size={14} /></button>
                  </div>
                </div>
              </div>
            </div>
