import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const getStockDeclaration: FunctionDeclaration = {
  name: 'get_stock',
  description: 'Obtiene la lista actual de stock de filamentos (rollos cerrados y abiertos).',
  parameters: { type: Type.OBJECT, properties: {} }
};

const updateStockDeclaration: FunctionDeclaration = {
  name: 'update_stock',
  description: 'Actualiza el stock de un filamento específico.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      color: { type: Type.STRING },
      type: { type: Type.STRING, enum: ['PLA', 'PET-G'] },
      closedCount: { type: Type.NUMBER },
      openCount: { type: Type.NUMBER }
    },
    required: ['color', 'type']
  }
};

const getOrdersDeclaration: FunctionDeclaration = {
  name: 'get_orders',
  description: 'Obtiene la lista de pedidos en la cola de producción.',
  parameters: { type: Type.OBJECT, properties: {} }
};

const addOrderDeclaration: FunctionDeclaration = {
  name: 'add_order',
  description: 'Registra un nuevo pedido en la cola.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      customer: { type: Type.STRING },
      details: { type: Type.STRING },
      priority: { type: Type.STRING, enum: ['Alta', 'Media', 'Baja'] }
    },
    required: ['customer', 'details']
  }
};

export class SinapsisBotService {
  constructor(
    private stock: any[], 
    private orders: any[], 
    private onStateChange: (newState: { stock?: any[], orders?: any[] }) => void
  ) {}

  async sendMessage(message: string, history: any[] = []) {
    // Creamos la instancia justo antes de usarla para asegurar que tome la API_KEY actual
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{
          functionDeclarations: [
            getStockDeclaration,
            updateStockDeclaration,
            getOrdersDeclaration,
            addOrderDeclaration
          ]
        }]
      }
    });

    // Podríamos reconstruir el historial aquí si fuera necesario, 
    // por ahora el chat de la SDK lo maneja en la sesión si se mantiene el objeto,
    // pero para despliegues serverless como Vercel, es mejor recrearlo o usar sendMessage directo.

    const result = await chat.sendMessage({ message });

    if (result.functionCalls) {
      const toolResponses: any[] = [];

      for (const call of result.functionCalls) {
        let response;
        if (call.name === 'get_stock') {
          response = { result: this.stock };
        } else if (call.name === 'update_stock') {
          const args = call.args as any;
          const updatedStock = this.stock.map(s => {
            if (s.color.toLowerCase() === args.color.toLowerCase() && s.type === args.type) {
              return { 
                ...s, 
                closedCount: args.closedCount !== undefined ? args.closedCount : s.closedCount,
                openCount: args.openCount !== undefined ? args.openCount : s.openCount
              };
            }
            return s;
          });
          this.onStateChange({ stock: updatedStock });
          response = { result: "Stock actualizado che! Quedó registrado el cambio. ✅" };
        } else if (call.name === 'get_orders') {
          response = { result: this.orders };
        } else if (call.name === 'add_order') {
          const { customer, details, priority = 'Media' } = call.args as any;
          const newOrder = {
            id: 'o' + Math.random().toString(36).substr(2, 4),
            customer,
            details,
            status: 'Pendiente',
            priority,
            createdAt: new Date().toISOString().split('T')[0]
          };
          const updatedOrders = [newOrder, ...this.orders];
          this.onStateChange({ orders: updatedOrders });
          response = { result: "Pedido anotado! Lo puse como pendiente 🖨️" };
        }

        toolResponses.push({
          id: call.id,
          name: call.name,
          response
        });
      }

      // Enviamos las respuestas de las funciones de vuelta al modelo
      const finalResult = await chat.sendMessage({
        message: "Operación completada con éxito." 
      });

      return finalResult.text;
    }

    return result.text;
  }
}

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import Layout from './components/Layout';
import ChatBot from './components/ChatBot';
import StockBoard from './components/StockBoard';
import OrderQueue from './components/OrderQueue';
import BudgetCalculator from './components/BudgetCalculator';
import { SinapsisBotService } from './services/geminiService';
import { StockItem, Order } from './types';
import { subscribeToStock, subscribeToOrders, updateStockItemInDb, addOrderToDb } from './services/firebaseService';
import { Cloud, CloudOff, Loader2, Key, Zap } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('chat');
  const [stock, setStock] = useState<StockItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSynced, setIsSynced] = useState(false);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  // Verificación de API Key (Solo necesaria en ciertos entornos de preview)
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      } else {
        // En producción (Vercel), asumimos que la llave está en process.env.API_KEY
        setHasApiKey(true);
      }
    };
    checkKey();
  }, []);

  // Suscripción a Firebase
  useEffect(() => {
    const unsubStock = subscribeToStock((newStock) => {
      setStock(newStock);
      setIsLoading(false);
      setIsSynced(true);
      setTimeout(() => setIsSynced(false), 2000);
    });

    const unsubOrders = subscribeToOrders((newOrders) => {
      setOrders(newOrders);
    });

    return () => {
      unsubStock();
      unsubOrders();
    };
  }, []);

  const handleUpdateStockItem = async (id: string, updates: Partial<StockItem>) => {
    const item = stock.find(s => s.id === id);
    if (item) {
      const updatedItem = { ...item, ...updates };
      await updateStockItemInDb(updatedItem);
    }
  };

  const onBotUpdate = useCallback(async (newState: { stock?: StockItem[], orders?: Order[] }) => {
    if (newState.stock) {
      newState.stock.forEach(async (item) => {
        await updateStockItemInDb(item);
      });
    }
    if (newState.orders) {
      const latestOrder = newState.orders[0];
      if (latestOrder) await addOrderToDb(latestOrder);
    }
  }, []);

  const botService = useMemo(() => 
    new SinapsisBotService(stock, orders, onBotUpdate), 
    [stock.length, orders.length, onBotUpdate]
  );

  const handleSendMessage = async (msg: string) => {
    try {
      return await botService.sendMessage(msg);
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) {
        // Si falla por falta de llave en el entorno de desarrollo, re-solicitamos
        if (window.aistudio) await window.aistudio.openSelectKey();
      }
      throw error;
    }
  };

  const handleOpenKeySelector = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true); // Asumimos éxito tras el diálogo
    }
  };

  if (isLoading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-50 gap-4">
        <Loader2 className="animate-spin text-indigo-600" size={48} />
        <p className="text-slate-500 font-medium animate-pulse">Conectando con Sinapsis 3D...</p>
      </div>
    );
  }

  // Pantalla de conexión de llave si es necesaria
  if (hasApiKey === false) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-slate-900 p-6">
        <div className="max-w-md w-full bg-white rounded-[2.5rem] p-10 text-center shadow-2xl">
          <div className="bg-indigo-600 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-lg shadow-indigo-200">
            <Zap size={40} className="text-white" fill="white" />
          </div>
          <h1 className="text-3xl font-black text-slate-900 mb-4 tracking-tight">¡Hola Lucas!</h1>
          <p className="text-slate-500 mb-8 leading-relaxed">
            Para que <strong>SinapsisBot</strong> pueda ayudarte, necesitamos vincularlo con tu cuenta de Google AI.
          </p>
          <button 
            onClick={handleOpenKeySelector}
            className="w-full bg-indigo-600 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100"
          >
            <Key size={20} />
            CONECTAR SINAPSISBOT
          </button>
          <p className="mt-6 text-[10px] text-slate-400 uppercase font-black tracking-widest">
            Sinapsis 3D - Gestión Inteligente
          </p>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="relative h-full">
        {/* Sync Indicator */}
        <div className={`absolute -top-6 right-0 flex items-center gap-1.5 transition-opacity duration-500 ${isSynced ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Nube Sincronizada</span>
        </div>

        <div className="animate-in fade-in slide-in-from-bottom-2 duration-500 h-full">
          {activeTab === 'chat' && <ChatBot onSendMessage={handleSendMessage} />}
          {activeTab === 'stock' && <StockBoard stock={stock} onUpdateStock={handleUpdateStockItem} />}
          {activeTab === 'queue' && <OrderQueue orders={orders} />}
          {activeTab === 'calc' && <BudgetCalculator />}
        </div>
      </div>
    </Layout>
  );
};

export default App;

