            <Bot size={24} />
          </div>
          <div>
            <h2 className="font-black uppercase tracking-tight text-sm">SinapsisBot</h2>
            <p className="text-[10px] text-orange-500 font-bold flex items-center gap-1.5 uppercase">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-pulse"></span> Sistema Operativo
            </p>
          </div>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/30">
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`
              max-w-[85%] flex gap-3 
              ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}
            `}>
              <div className={`
                w-9 h-9 rounded-2xl flex items-center justify-center shrink-0 mt-1 shadow-sm
                ${msg.role === 'user' ? 'bg-slate-950 text-white' : 'bg-orange-600 text-white'}
              `}>
                {msg.role === 'user' ? <User size={18} /> : <Bot size={18} />}
              </div>
              <div className={`
                p-5 rounded-3xl text-sm leading-relaxed shadow-sm
                ${msg.role === 'user' ? 'bg-slate-950 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}
              `}>
                {msg.text}
                <div className={`text-[9px] mt-2 font-bold opacity-40 uppercase tracking-widest ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                  {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </div>
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start animate-in fade-in slide-in-from-left-2">
            <div className="flex gap-3 items-center bg-white px-6 py-4 rounded-3xl shadow-sm border border-slate-100">
              <div className="flex gap-1">
                <span className="w-1.5 h-1.5 bg-orange-600 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                <span className="w-1.5 h-1.5 bg-orange-600 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                <span className="w-1.5 h-1.5 bg-orange-600 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
              </div>
              <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Analizando</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 bg-white border-t border-slate-100">
        <div className="flex flex-wrap gap-2 mb-4">
          {suggestions.map((s, idx) => (
            <button
              key={idx}
              onClick={() => handleSend(s.text)}
              disabled={isLoading}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-2xl text-xs font-bold border transition-all hover:scale-105 active:scale-95 disabled:opacity-50 ${s.color}`}
            >
              {s.icon}
              {s.text}
            </button>
          ))}
        </div>
        <form 
          onSubmit={(e) => { e.preventDefault(); handleSend(); }}
          className="flex gap-3"
        >
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Escribí acá, che..."
            className="flex-1 bg-slate-100 border-none rounded-2xl px-6 py-4 text-sm focus:outline-none focus:ring-2 focus:ring-orange-600 transition-all font-medium"
          />
