            <input 
              type="text"
              placeholder="Buscar color..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-2xl pl-12 pr-10 py-3 text-sm focus:ring-2 focus:ring-orange-600 transition-all font-medium"
            />
            {searchTerm && (
              <button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-slate-200 rounded-full text-slate-400">
                <X size={14} />
              </button>
            )}
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-fit">
            <button 
              onClick={() => setActiveType(FilamentType.PLA)}
              className={`flex-1 md:px-8 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeType === FilamentType.PLA ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              PLA
