                  value={weight}
                  onChange={(e) => setWeight(e.target.value ? Number(e.target.value) : '')}
                  className="w-full bg-slate-50 border-none rounded-2xl pl-14 pr-6 py-4 focus:ring-2 focus:ring-orange-600 font-bold text-lg text-slate-900"
                  placeholder="Ej: 150"
                />
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Perfil de Cliente</label>
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={() => setClientType('minorista')}
                  className={`py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all border-2 ${clientType === 'minorista' ? 'bg-orange-600 text-white border-orange-600 shadow-lg shadow-orange-600/20' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'}`}
                >
                  Minorista
                </button>
                <button
                  onClick={() => setClientType('mayorista')}
                  className={`py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all border-2 ${clientType === 'mayorista' ? 'bg-orange-600 text-white border-orange-600 shadow-lg shadow-orange-600/20' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'}`}
                >
                  Mayorista
                </button>
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Costo Filamento ($/kg)</label>
              <div className="relative group">
                <DollarSign className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-orange-600 transition-colors" size={20} />
                <input
                  type="number"
                  value={filamentPrice}
