import React, { useState } from 'react';
import { StockItem, FilamentType } from '../types';
import { Droplet, Plus, Minus, AlertCircle, Search, X } from 'lucide-react';

interface StockBoardProps {
  stock: StockItem[];
  onUpdateStock?: (id: string, updates: Partial<StockItem>) => void;
}

const StockBoard: React.FC<StockBoardProps> = ({ stock, onUpdateStock }) => {
  const [activeType, setActiveType] = useState<FilamentType>(FilamentType.PLA);
  const [searchTerm, setSearchTerm] = useState('');

  const checkAlert = (item: StockItem) => {
    if (item.type === FilamentType.PETG) {
      return item.closedCount < 1; // Para PET-G todo es mínimo 1
    }
    const isCriticalColor = item.color === "Blanco" || item.color === "Negro";
    const minClosed = isCriticalColor ? 3 : 1;
    return item.closedCount < minClosed;
  };

  const filteredStock = stock
    .filter(item => item.type === activeType)
    .filter(item => item.color.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => {
      const aAlert = checkAlert(a);
      const bAlert = checkAlert(b);
      if (aAlert && !bAlert) return -1;
      if (!aAlert && bAlert) return 1;
      return a.color.localeCompare(b.color);
    });

  const updateCount = (id: string, field: 'closedCount' | 'openCount', delta: number) => {
    const item = stock.find(s => s.id === id);
    if (!item || !onUpdateStock) return;
    const newVal = Math.max(0, item[field] + delta);
    onUpdateStock(id, { [field]: newVal });
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-2xl font-black text-slate-950 uppercase tracking-tight">Inventario Filamentos</h2>
          <p className="text-slate-500 text-sm font-medium">Gestioná el stock de Sinapsis 3D</p>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-4">
          <div className="relative w-full md:w-64 group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-600 transition-colors" size={18} />
            <input 
              type="text"
              placeholder="Buscar color..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-2xl pl-12 pr-10 py-3 text-sm focus:ring-2 focus:ring-orange-600 transition-all font-medium"
            />
            {searchTerm && (
              <button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-slate-200 rounded-full text-slate-400">
                <X size={14} />
              </button>
            )}
          </div>

          <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-fit">
            <button 
              onClick={() => setActiveType(FilamentType.PLA)}
              className={`flex-1 md:px-8 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeType === FilamentType.PLA ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              PLA
            </button>
            <button 
              onClick={() => setActiveType(FilamentType.PETG)}
              className={`flex-1 md:px-8 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeType === FilamentType.PETG ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              PET-G
            </button>
          </div>
        </div>
      </div>

      {filteredStock.length === 0 ? (
        <div className="h-64 flex flex-col items-center justify-center bg-white rounded-[2rem] border border-dashed border-slate-200">
          <Droplet className="text-slate-200 mb-4" size={48} />
          <p className="text-slate-400 font-medium">No encontramos ese color.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {filteredStock.map((item) => {
            const isLow = checkAlert(item);
            return (
              <div key={item.id} className={`group bg-white p-6 rounded-[2.5rem] shadow-sm border transition-all duration-300 hover:shadow-xl hover:-translate-y-1 ${isLow ? 'border-orange-200 bg-orange-50/10' : 'border-slate-100'} flex flex-col gap-6`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <div 
                      className="w-12 h-12 rounded-[1.25rem] shadow-inner flex items-center justify-center transition-transform group-hover:scale-110"
                      style={{ backgroundColor: getHexColor(item.color) }}
                    >
                      <Droplet size={20} className={isDark(item.color) ? 'text-white/40' : 'text-black/20'} />
                    </div>
                    <div>
                      <h3 className="font-black text-slate-900 leading-tight uppercase tracking-tight">{item.color}</h3>
                      {isLow && (
                        <span className="text-[10px] font-black text-orange-600 uppercase flex items-center gap-1.5 mt-1 bg-orange-100/50 px-2 py-0.5 rounded-full w-fit">
                          <AlertCircle size={10} /> Reponer
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-slate-50 p-4 rounded-3xl border border-slate-100 flex flex-col items-center text-center">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Cerrados</p>
                    <div className="flex items-center justify-between w-full">
                      <button onClick={() => updateCount(item.id, 'closedCount', -1)} className="w-8 h-8 flex items-center justify-center hover:bg-white rounded-xl text-slate-400 transition-colors shadow-sm"><Minus size={16} /></button>
                      <span className={`font-black text-2xl ${isLow ? 'text-orange-600' : 'text-slate-900'}`}>{item.closedCount}</span>
                      <button onClick={() => updateCount(item.id, 'closedCount', 1)} className="w-8 h-8 flex items-center justify-center hover:bg-white rounded-xl text-orange-600 transition-colors shadow-sm"><Plus size={16} /></button>
                    </div>
                  </div>
                  <div className="bg-slate-50 p-4 rounded-3xl border border-slate-100 flex flex-col items-center text-center">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Abiertos</p>
                    <div className="flex items-center justify-between w-full">
                      <button onClick={() => updateCount(item.id, 'openCount', -1)} className="w-8 h-8 flex items-center justify-center hover:bg-white rounded-xl text-slate-400 transition-colors shadow-sm"><Minus size={16} /></button>
                      <span className="font-black text-2xl text-slate-900">{item.openCount}</span>
                      <button onClick={() => updateCount(item.id, 'openCount', 1)} className="w-8 h-8 flex items-center justify-center hover:bg-white rounded-xl text-orange-600 transition-colors shadow-sm"><Plus size={16} /></button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {filteredStock.some(checkAlert) && !searchTerm && (
        <div className="bg-orange-600 text-white p-6 rounded-[2rem] flex items-center gap-5 shadow-lg shadow-orange-600/20 animate-in slide-in-from-bottom-4">
          <div className="bg-white/20 p-3 rounded-2xl">
            <AlertCircle size={28} />
          </div>
          <div>
            <p className="font-black uppercase tracking-tight text-sm mb-0.5">Atención Operativa</p>
            <p className="text-orange-50 text-xs font-medium leading-relaxed opacity-90">
              Hay colores bajo el mínimo. Se muestran al principio de la lista.
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

function getHexColor(color: string) {
  const map: any = {
    "Negro": "#1a1a1a", "Blanco": "#ffffff", "Gris": "#94a3b8", "Gris claro": "#cbd5e1",
    "Gris Plata": "#e2e8f0", "Azul": "#2563eb", "Celeste": "#60a5fa", "Aqua": "#2dd4bf",
    "Rojo": "#dc2626", "Dorado": "#fbbf24", "Amarillo": "#fde047", "Naranja": "#f97316",
    "Piel": "#ffedd5", "Verde claro": "#4ade80", "Verde Oscuro": "#166534", "Rosa": "#f472b6",
    "Violeta": "#8b5cf6", "Lila": "#ddd6fe", "Fucsia": "#db2777", "Marron": "#78350f",
    "Marron chocolate": "#451a03", "Celeste claro (pastel)": "#bfdbfe"
  };
  return map[color] || "#ccc";
}

function isDark(color: string) {
  const darks = ["Negro", "Azul", "Rojo", "Verde Oscuro", "Marron", "Marron chocolate", "Violeta", "Fucsia"];
  return darks.includes(color);
}

