import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, Sparkles, Scale, AlertTriangle, Trash2, MessageSquarePlus } from 'lucide-react';
import { ChatMessage } from '../types';

interface ChatBotProps {
  onSendMessage: (msg: string) => Promise<string>;
}

const ChatBot: React.FC<ChatBotProps> = ({ onSendMessage }) => {
  const [messages, setMessages] = useState<ChatMessage[]>(() => {
    const saved = localStorage.getItem('sinapsis_chat_history');
    if (saved) {
      const parsed = JSON.parse(saved);
      return parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }));
    }
    return [{ 
      role: 'model', 
      text: '¡Hola! Bienvenido al centro operativo de Sinapsis 3D. ¿En qué puedo ayudarte hoy con el stock o los presupuestos? 🖨️🇦🇷', 
      timestamp: new Date() 
    }];
  });

  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const suggestions = [
    { text: "¿Qué filamento tengo que reponer?", icon: <AlertTriangle size={14} />, color: "bg-orange-50 text-orange-700 border-orange-200" },
    { text: "Calcular nuevo presupuesto", icon: <Scale size={14} />, color: "bg-slate-50 text-slate-700 border-slate-200" },
    { text: "¿Cómo vienen los pedidos?", icon: <Sparkles size={14} />, color: "bg-blue-50 text-blue-700 border-blue-200" }
  ];

  useEffect(() => {
    localStorage.setItem('sinapsis_chat_history', JSON.stringify(messages));
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  const handleClearChat = () => {
    if (confirm('¿Estás seguro de que querés borrar el historial del chat?')) {
      const initialMsg: ChatMessage = { 
        role: 'model', 
        text: 'Historial borrado. ¿En qué puedo ayudarte ahora?', 
        timestamp: new Date() 
      };
      setMessages([initialMsg]);
      localStorage.removeItem('sinapsis_chat_history');
    }
  };

  const handleNewContext = () => {
    const initialMsg: ChatMessage = { 
      role: 'model', 
      text: 'Nueva ventana de contexto iniciada. Los datos anteriores ya no influyen en esta charla.', 
      timestamp: new Date() 
    };
    setMessages([initialMsg]);
  };

  const handleSend = async (textToSend?: string) => {
    const messageText = textToSend || input;
    if (!messageText.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: messageText, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await onSendMessage(messageText);
      const modelMsg: ChatMessage = { role: 'model', text: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("Chat Error:", error);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: 'Lo lamento, hubo un error en la conexión con el servidor. Por favor, intente nuevamente.', 
        timestamp: new Date() 
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-10rem)] bg-white rounded-[2rem] shadow-xl border border-slate-200 overflow-hidden">
      <div className="p-5 bg-slate-950 text-white flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="bg-orange-600 p-2.5 rounded-2xl shadow-lg">
            <Bot size={24} />
          </div>
          <div>
            <h2 className="font-black uppercase tracking-tight text-sm">SinapsisBot</h2>
            <p className="text-[10px] text-orange-500 font-bold flex items-center gap-1.5 uppercase">
              <span className="w-2 h-2 bg-orange-500 rounded-full animate-pulse"></span> Asistente Inteligente
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={handleNewContext}
            title="Nueva Ventana de Contexto"
            className="p-2 hover:bg-slate-800 rounded-xl text-slate-400 transition-colors"
          >
            <MessageSquarePlus size={20} />
          </button>
          <button 
            onClick={handleClearChat}
            title="Borrar Historial"
            className="p-2 hover:bg-red-900/30 rounded-xl text-slate-400 hover:text-red-500 transition-colors"
          >
            <Trash2 size={20} />
          </button>
        </div>
      </div>

