import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";
import { SYSTEM_INSTRUCTION, FILAMENT_PRICE_PER_KILO } from "../constants";

const getStockDeclaration: FunctionDeclaration = {
  name: 'get_stock',
  description: 'Obtiene la lista actual y detallada del stock de filamentos (color, tipo, rollos cerrados y abiertos).',
  parameters: { type: Type.OBJECT, properties: {} }
};

const updateStockDeclaration: FunctionDeclaration = {
  name: 'update_stock',
  description: 'Actualiza el stock de un filamento específico.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      color: { type: Type.STRING },
      type: { type: Type.STRING, enum: ['PLA', 'PET-G'] },
      closedCount: { type: Type.NUMBER },
      openCount: { type: Type.NUMBER }
    },
    required: ['color', 'type']
  }
};

const calculateBudgetDeclaration: FunctionDeclaration = {
  name: 'calculate_budget',
  description: 'Calcula el precio sugerido de una impresión basado en el peso y tipo de cliente.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      weight: { type: Type.NUMBER, description: 'Peso en gramos' },
      clientType: { type: Type.STRING, enum: ['minorista', 'mayorista'] },
      filamentPrice: { type: Type.NUMBER, description: 'Precio por kilo de filamento' }
    },
    required: ['weight', 'clientType']
  }
};

const getOrdersDeclaration: FunctionDeclaration = {
  name: 'get_orders',
  description: 'Obtiene la lista de pedidos en producción.',
  parameters: { type: Type.OBJECT, properties: {} }
};

export class SinapsisBotService {
  constructor(
    private stock: any[], 
    private orders: any[], 
    private onStateChange: (newState: { stock?: any[], orders?: any[] }) => void
  ) {}

  async sendMessage(message: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{
          functionDeclarations: [
            getStockDeclaration,
            updateStockDeclaration,
            getOrdersDeclaration,
            calculateBudgetDeclaration
          ]
        }]
      }
    });

    try {
      let result = await chat.sendMessage({ message });

      // Manejo de llamadas a funciones
      if (result.functionCalls) {
        const toolResponses: any[] = [];

        for (const call of result.functionCalls) {
          let responseData;

          if (call.name === 'get_stock') {
            responseData = { result: this.stock };
          } else if (call.name === 'calculate_budget') {
            const { weight, clientType, filamentPrice = FILAMENT_PRICE_PER_KILO } = call.args as any;
            const costPerGram = filamentPrice / 1000;
            const materialCost = costPerGram * weight;
            const baseCost = materialCost * 1.4;
            const multiplier = clientType === 'minorista' ? 4 : 3;
            const finalPrice = Math.round((baseCost * multiplier) / 100) * 100;
            responseData = { result: { finalPrice, materialCost, baseCost, details: `Peso: ${weight}g, Cliente: ${clientType}` } };
          } else if (call.name === 'update_stock') {
            const args = call.args as any;
            const updatedStock = this.stock.map(s => {
              if (s.color.toLowerCase() === args.color.toLowerCase() && s.type === args.type) {
                return { 
                  ...s, 
                  closedCount: args.closedCount ?? s.closedCount,
                  openCount: args.openCount ?? s.openCount
                };
              }
              return s;
            });
            this.onStateChange({ stock: updatedStock });
            responseData = { result: "Stock actualizado en la base de datos." };
          } else if (call.name === 'get_orders') {
            responseData = { result: this.orders };
          }

          toolResponses.push({
            id: call.id,
            name: call.name,
            response: responseData
          });
        }

        const finalResult = await chat.sendMessage({
          message: "Datos obtenidos correctamente. Por favor, generá la respuesta final para el usuario siguiendo estrictamente las reglas de formato y priorización indicadas en tus instrucciones del sistema (PLA primero, lista puntual)."
        });
        return finalResult.text;
      }

      return result.text;
    } catch (err) {
      console.error("Error en SinapsisBotService:", err);
      throw err;
    }
  }
}

