  description: 'Calcula el precio sugerido de una impresión.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      weight: { type: Type.NUMBER },
      clientType: { type: Type.STRING, enum: ['minorista', 'mayorista'] },
      filamentPrice: { type: Type.NUMBER }
    },
    required: ['weight', 'clientType']
  }
};

const getOrdersDeclaration: FunctionDeclaration = {
  name: 'get_orders',
  description: 'Obtiene la lista de pedidos.',
  parameters: { type: Type.OBJECT, properties: {} }
};

export class SinapsisBotService {
  constructor(
    private stock: any[], 
    private orders: any[], 
    private onStateChange: (newState: { stock?: any[], orders?: any[] }) => void
  ) {}

  async sendMessage(message: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{
          functionDeclarations: [
            getStockDeclaration,
            updateStockDeclaration,
            getOrdersDeclaration,
            calculateBudgetDeclaration
          ]
        }]
      }
    });

    try {
      let result = await chat.sendMessage({ message });

      if (result.functionCalls) {
        const toolResponses: any[] = [];

        for (const call of result.functionCalls) {
          let responseData;

          if (call.name === 'get_stock') {
            responseData = { result: this.stock };
          } else if (call.name === 'calculate_budget') {
            const { weight, clientType, filamentPrice = FILAMENT_PRICE_PER_KILO } = call.args as any;
            const costPerGram = filamentPrice / 1000;
            const materialCost = costPerGram * weight;
            const baseCost = materialCost * 1.4;
            const multiplier = clientType === 'minorista' ? 4 : 3;
            const finalPrice = Math.round((baseCost * multiplier) / 100) * 100;
            responseData = { result: { finalPrice, details: `Peso: ${weight}g, Cliente: ${clientType}` } };
          } else if (call.name === 'update_stock') {
            const args = call.args as any;
            const updatedStock = this.stock.map(s => {
              if (s.color.toLowerCase() === args.color.toLowerCase() && s.type === args.type) {
                return { 
                  ...s, 
                  closedCount: args.closedCount ?? s.closedCount,
                  openCount: args.openCount ?? s.openCount
                };
              }
              return s;
            });
            this.onStateChange({ stock: updatedStock });
            responseData = { result: "OK" };
          } else if (call.name === 'get_orders') {
            responseData = { result: this.orders };
          }

          toolResponses.push({
            id: call.id,
            name: call.name,
            response: responseData
          });
        }

        const finalResult = await chat.sendMessage({
          message: "REGLA: Revisá CADA ÍTEM del stock sin omitir ninguno. Si un color tiene menos cerrados que el mínimo, INCLUILO. Priorizá PLA arriba de todo. Formato lista puntual."
        });
        return finalResult.text;
      }

      return result.text;
    } catch (err) {
      console.error("SinapsisBot Error:", err);
      throw err;
    }
  }
}

import React, { useState } from 'react';
import { StockItem, FilamentType } from '../types';
import { Droplet, Plus, Minus, AlertCircle, Search, X, Layers } from 'lucide-react';

interface StockBoardProps {
  stock: StockItem[];
  onUpdateStock?: (id: string, updates: Partial<StockItem>) => void;
}

const StockBoard: React.FC<StockBoardProps> = ({ stock, onUpdateStock }) => {
  const [activeType, setActiveType] = useState<FilamentType>(FilamentType.PLA);
  const [searchTerm, setSearchTerm] = useState('');

  const checkAlert = (item: StockItem) => {
    if (item.type === FilamentType.PETG) {
      return item.closedCount < 1;
    }
    const isCriticalColor = item.color === "Blanco" || item.color === "Negro";
    const minClosed = isCriticalColor ? 3 : 1;
    return item.closedCount < minClosed;
  };

  const getMinRequired = (item: StockItem) => {
    if (item.type === FilamentType.PETG) return 1;
    return (item.color === "Blanco" || item.color === "Negro") ? 3 : 1;
  };

  const filteredStock = stock
    .filter(item => item.type === activeType)
    .filter(item => item.color.toLowerCase().includes(searchTerm.toLowerCase()))
    .sort((a, b) => {
      const aAlert = checkAlert(a);
      const bAlert = checkAlert(b);
      if (aAlert && !bAlert) return -1;
      if (!aAlert && bAlert) return 1;
      return a.color.localeCompare(b.color);
    });

  const updateCount = (id: string, field: 'closedCount' | 'openCount', delta: number) => {
    const item = stock.find(s => s.id === id);
    if (!item || !onUpdateStock) return;
    const newVal = Math.max(0, item[field] + delta);
    onUpdateStock(id, { [field]: newVal });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="bg-orange-600/10 p-3 rounded-2xl text-orange-600">
            <Layers size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black text-slate-950 uppercase tracking-tight leading-none">Inventario</h2>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-1">Sinapsis 3D Bariloche</p>
          </div>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-3">
          <div className="relative w-full md:w-64 group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-orange-600 transition-colors" size={16} />
            <input 
              type="text"
              placeholder="Buscar color..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-slate-50 border-none rounded-xl pl-10 pr-8 py-2.5 text-xs focus:ring-2 focus:ring-orange-600 transition-all font-bold"
            />
            {searchTerm && (
              <button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-300">
                <X size={14} />
              </button>
            )}
          </div>

          <div className="flex bg-slate-100 p-1 rounded-xl w-full md:w-fit">
            <button 
              onClick={() => setActiveType(FilamentType.PLA)}
              className={`flex-1 md:px-6 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeType === FilamentType.PLA ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500'}`}
            >
              PLA
            </button>
            <button 
              onClick={() => setActiveType(FilamentType.PETG)}
              className={`flex-1 md:px-6 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activeType === FilamentType.PETG ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500'}`}
            >
              PET-G
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] border border-slate-100 shadow-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Color</th>
                <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">Cerrados</th>
                <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">Abiertos</th>
                <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">Estado</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStock.map((item) => {
                const isLow = checkAlert(item);
                const min = getMinRequired(item);
                return (
                  <tr key={item.id} className={`hover:bg-slate-50/50 transition-colors ${isLow ? 'bg-orange-50/20' : ''}`}>
                    <td className="px-8 py-4">
                      <div className="flex items-center gap-4">
                        <div 
                          className="w-10 h-10 rounded-xl shadow-inner border border-black/5 shrink-0"
                          style={{ backgroundColor: getHexColor(item.color) }}
                        />
                        <div>
                          <p className="font-black text-slate-900 uppercase text-sm tracking-tight">{item.color}</p>
                          <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{item.type}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-center gap-4 bg-slate-100/50 w-fit mx-auto px-4 py-2 rounded-xl">
                        <button onClick={() => updateCount(item.id, 'closedCount', -1)} className="text-slate-400 hover:text-red-500"><Minus size={14} /></button>
                        <span className={`font-black text-lg min-w-[2ch] text-center ${isLow ? 'text-orange-600' : 'text-slate-900'}`}>{item.closedCount}</span>
                        <button onClick={() => updateCount(item.id, 'closedCount', 1)} className="text-orange-600"><Plus size={14} /></button>
                      </div>
                      <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest text-center mt-1">Min: {min}</p>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex items-center justify-center gap-4 bg-slate-100/50 w-fit mx-auto px-4 py-2 rounded-xl">
                        <button onClick={() => updateCount(item.id, 'openCount', -1)} className="text-slate-400"><Minus size={14} /></button>
                        <span className="font-black text-lg min-w-[2ch] text-center text-slate-900">{item.openCount}</span>
                        <button onClick={() => updateCount(item.id, 'openCount', 1)} className="text-orange-600"><Plus size={14} /></button>
                      </div>
                    </td>
                    <td className="px-8 py-4 text-right">
                      {isLow ? (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-orange-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest shadow-lg shadow-orange-600/20">
                          <AlertCircle size={10} /> Reponer
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-green-100 text-green-700 rounded-lg text-[9px] font-black uppercase tracking-widest">
                          OK
                        </span>
                      )}
                    </td>
                  </tr>
                );
              })}
              {filteredStock.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <p className="text-slate-300 font-black uppercase tracking-widest text-xs">No hay colores que coincidan</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

function getHexColor(color: string) {
  const map: any = {
    "Negro": "#1a1a1a", "Blanco": "#ffffff", "Gris": "#94a3b8", "Gris claro": "#cbd5e1",
    "Gris Plata": "#e2e8f0", "Azul": "#2563eb", "Celeste": "#60a5fa", "Aqua": "#2dd4bf",
    "Rojo": "#dc2626", "Dorado": "#fbbf24", "Amarillo": "#fde047", "Naranja": "#f97316",
    "Piel": "#ffedd5", "Verde claro": "#4ade80", "Verde Oscuro": "#166534", "Rosa": "#f472b6",
    "Violeta": "#8b5cf6", "Lila": "#ddd6fe", "Fucsia": "#db2777", "Marron": "#78350f",
    "Marron chocolate": "#451a03", "Celeste claro (pastel)": "#bfdbfe"
  };
  return map[color] || "#ccc";
}

