      callback(snapshot.data());
    } else {
      // Fix: Use settingsRef directly to avoid "Property 'ref' does not exist on type 'never'"
      // which can occur when TypeScript narrows 'snapshot' in the else block.
      setDoc(settingsRef, { 
        plaPrice: DEFAULT_PLA_PRICE,
        petgPrice: DEFAULT_PETG_PRICE 
      });
