import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";

const getStockDeclaration: FunctionDeclaration = {
  name: 'get_stock',
  description: 'Obtiene el estado actual real del stock.',
  parameters: { type: Type.OBJECT, properties: {} }
};

const updateStockDeclaration: FunctionDeclaration = {
  name: 'update_stock',
  description: 'Actualiza el stock de un filamento específico.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      color: { type: Type.STRING },
      type: { type: Type.STRING, enum: ['PLA', 'PET-G'] },
      closedCount: { type: Type.NUMBER },
      openCount: { type: Type.NUMBER }
    },
    required: ['color', 'type']
  }
};

const calculateBudgetDeclaration: FunctionDeclaration = {
  name: 'calculate_budget',
  description: 'Calcula el precio de impresión basándose en el peso, tipo de cliente, material y tiempo de diseño.',
  parameters: {
    type: Type.OBJECT,
    properties: {
      weight: { type: Type.NUMBER },
      clientType: { type: Type.STRING, enum: ['minorista', 'mayorista'] },
      filamentType: { type: Type.STRING, enum: ['PLA', 'PET-G'] },
      designMinutes: { type: Type.NUMBER, description: 'Tiempo de diseño personalizado en minutos. Por defecto 0.' }
    },
    required: ['weight', 'clientType', 'filamentType']
  }
};

export class SinapsisBotService {
  constructor(
    private stock: any[], 
    private orders: any[], 
    private prices: { pla: number, petg: number, design: number },
    private onStateChange: (newState: { stock?: any[], orders?: any[] }) => void
  ) {}

  async sendMessage(message: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        tools: [{
          functionDeclarations: [
            getStockDeclaration,
            updateStockDeclaration,
            calculateBudgetDeclaration
          ]
        }]
      }
    });

    try {
      let result = await chat.sendMessage({ message });

      if (result.functionCalls) {
        const toolResponses: any[] = [];

        for (const call of result.functionCalls) {
          let responseData;

          if (call.name === 'get_stock') {
            const stockReport = this.stock.map(s => {
              const min = s.type === 'PET-G' ? 1 : (s.color === 'Blanco' || s.color === 'Negro' ? 3 : 1);
              return `COLOR: ${s.color} | TIPO: ${s.type} | CERRADOS: ${s.closedCount} | MINIMO: ${min} | STATUS: ${s.closedCount < min ? 'FALTA' : 'OK'}`;
            }).join('\n');
            responseData = { result: stockReport };
          } else if (call.name === 'calculate_budget') {
            const { weight, clientType, filamentType, designMinutes = 0 } = call.args as any;
            const currentPrice = filamentType === 'PET-G' ? this.prices.petg : this.prices.pla;

            const costPerGram = currentPrice / 1000;
            const materialCost = costPerGram * weight;
            const baseCost = materialCost * 1.4;
            const multiplier = clientType === 'minorista' ? 4 : 3;
            const printingPrice = Math.round((baseCost * multiplier) / 100) * 100;

            const designCost = (this.prices.design / 60) * designMinutes;
            const finalPrice = printingPrice + designCost;

            responseData = { 
              result: { 
                finalPrice, 
                printingPrice,
                designCost,
                details: `Calculado para ${weight}g (${clientType}) en ${filamentType} con ${designMinutes} min de diseño. Costo $/kg: ${currentPrice}, $/hr diseño: ${this.prices.design}` 
              } 
            };
          }

          toolResponses.push({
            id: call.id,
            name: call.name,
            response: responseData
          });
        }

        const finalResult = await chat.sendMessage({
          message: "Generá la respuesta final con el presupuesto calculado detallando el costo de impresión y el costo de diseño si corresponde."
        });
        return finalResult.text;
      }

      return result.text;
    } catch (err) {
      console.error("SinapsisBot Error:", err);
      throw err;
    }
  }
}

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import Layout from './components/Layout';
import ChatBot from './components/ChatBot';
import StockBoard from './components/StockBoard';
import OrderQueue from './components/OrderQueue';
import BudgetCalculator from './components/BudgetCalculator';
import { SinapsisBotService } from './services/geminiService';
import { StockItem, Order, FilamentType } from './types';
import { subscribeToStock, subscribeToOrders, subscribeToSettings, updateStockItemInDb, addOrderToDb, updateSettings } from './services/firebaseService';
import { DEFAULT_PLA_PRICE, DEFAULT_PETG_PRICE, DEFAULT_DESIGN_PRICE } from './constants';
import { Loader2, Key, Zap } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('chat');
  const [stock, setStock] = useState<StockItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [plaPrice, setPlaPrice] = useState<number>(DEFAULT_PLA_PRICE);
  const [petgPrice, setPetgPrice] = useState<number>(DEFAULT_PETG_PRICE);
  const [designPrice, setDesignPrice] = useState<number>(DEFAULT_DESIGN_PRICE);
  const [isLoading, setIsLoading] = useState(true);
  const [isSynced, setIsSynced] = useState(false);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && typeof window.aistudio.hasSelectedApiKey === 'function') {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      } else {
        setHasApiKey(true);
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    const unsubStock = subscribeToStock((newStock) => {
      setStock(newStock);
      setIsLoading(false);
      setIsSynced(true);
      setTimeout(() => setIsSynced(false), 2000);
    });

    const unsubOrders = subscribeToOrders((newOrders) => {
      setOrders(newOrders);
    });

    const unsubSettings = subscribeToSettings((settings) => {
      if (settings?.plaPrice) setPlaPrice(settings.plaPrice);
      if (settings?.petgPrice) setPetgPrice(settings.petgPrice);
      if (settings?.designPrice) setDesignPrice(settings.designPrice);
    });

    return () => {
      unsubStock();
      unsubOrders();
      unsubSettings();
    };
  }, []);

  const handleUpdateStockItem = async (id: string, updates: Partial<StockItem>) => {
    const item = stock.find(s => s.id === id);
    if (item) {
      await updateStockItemInDb({ ...item, ...updates });
    }
  };

  const handleUpdatePrices = async (updates: { pla?: number, petg?: number, design?: number }) => {
    await updateSettings({ 
      ...(updates.pla && { plaPrice: updates.pla }),
      ...(updates.petg && { petgPrice: updates.petg }),
      ...(updates.design && { designPrice: updates.design })
    });
  };

  const onBotUpdate = useCallback(async (newState: { stock?: StockItem[], orders?: Order[] }) => {
    if (newState.stock) {
      for (const item of newState.stock) await updateStockItemInDb(item);
    }
    if (newState.orders && newState.orders[0]) await addOrderToDb(newState.orders[0]);
  }, []);

  const botService = useMemo(() => 
    new SinapsisBotService(stock, orders, { pla: plaPrice, petg: petgPrice, design: designPrice }, onBotUpdate), 
    [stock, orders, plaPrice, petgPrice, designPrice, onBotUpdate]
  );

  const handleSendMessage = async (msg: string) => {
    try {
      return await botService.sendMessage(msg);
    } catch (error: any) {
      if (error.message?.includes("Requested entity was not found")) {
        if (window.aistudio) await window.aistudio.openSelectKey();
      }
      throw error;
    }
  };

  if (isLoading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-50 gap-4">
        <Loader2 className="animate-spin text-orange-600" size={48} />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs animate-pulse">Conectando con Sinapsis 3D...</p>
      </div>
    );
  }

  if (hasApiKey === false) {
    return (
      <div className="h-screen w-screen flex items-center justify-center bg-slate-900 p-6">
        <div className="max-w-md w-full bg-white rounded-[2.5rem] p-10 text-center shadow-2xl">
          <div className="bg-orange-600 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8">
            <Zap size={40} className="text-white" fill="white" />
          </div>
          <h1 className="text-3xl font-black text-slate-900 mb-4 tracking-tight uppercase">SINAPSISBOT</h1>
          <button 
            onClick={() => window.aistudio?.openSelectKey().then(() => setHasApiKey(true))}
            className="w-full bg-orange-600 text-white font-black py-4 rounded-2xl shadow-xl shadow-orange-600/20 uppercase tracking-widest text-xs"
          >
            CONECTAR LLAVE AI
          </button>
        </div>
      </div>
    );
  }

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      <div className="relative h-full">
        <div className={`absolute -top-6 right-0 flex items-center gap-1.5 transition-opacity duration-500 ${isSynced ? 'opacity-100' : 'opacity-0'}`}>
          <div className="w-2 h-2 bg-green-500 rounded-full"></div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Nube OK</span>
        </div>
        {activeTab === 'chat' && <ChatBot onSendMessage={handleSendMessage} />}
        {activeTab === 'stock' && <StockBoard stock={stock} onUpdateStock={handleUpdateStockItem} />}
        {activeTab === 'queue' && <OrderQueue orders={orders} />}
        {activeTab === 'calc' && (
          <BudgetCalculator 
            plaPrice={plaPrice} 
            petgPrice={petgPrice}
            designPrice={designPrice}
            onUpdatePrices={handleUpdatePrices} 
          />
        )}
      </div>
    </Layout>
  );
};

export default App;

