interface BudgetCalculatorProps {
  plaPrice: number;
  petgPrice: number;
  designPrice: number;
  postProcessPrice: number;
  onUpdatePrices: (updates: { pla?: number, petg?: number, design?: number, postProcess?: number }) => void;
}

