import { StockItem, Order, Printer } from '../types';
import { INITIAL_STOCK, INITIAL_ORDERS, INITIAL_PRINTERS, DEFAULT_PLA_PRICE, DEFAULT_PETG_PRICE, DEFAULT_DESIGN_PRICE, DEFAULT_POST_PROCESS_PRICE } from '../constants';

